package com.transformertwin.api;
import com.transformertwin.api.dto.ApiDtos; import com.transformertwin.api.dto.ApiDtos.*; import com.transformertwin.domain.*; import com.transformertwin.repository.*;
import com.transformertwin.service.*; import jakarta.validation.Valid;
import org.springframework.data.domain.*; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api")
public class TransformerController {
 private final TransformerService service; private final SensorReadingRepository readings; private final DiagnosticTestRepository diagnostics; private final AlertRepository alerts; private final RealtimeService realtime; private final DgaAnalysisService dga; private final MaintenanceRecordRepository maintenance; private final AlertNotificationRepository notifications; private final HealthAssessmentRepository healthAssessments;
 public TransformerController(TransformerService s,SensorReadingRepository r,DiagnosticTestRepository d,AlertRepository a,RealtimeService rt,DgaAnalysisService dga,MaintenanceRecordRepository maintenance,AlertNotificationRepository notifications,HealthAssessmentRepository healthAssessments){service=s;readings=r;diagnostics=d;alerts=a;realtime=rt;this.dga=dga;this.maintenance=maintenance;this.notifications=notifications;this.healthAssessments=healthAssessments;}
 @GetMapping("/transformers") public PageResponse<TransformerView> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size){return service.list(page,clamp(size));}
 @PostMapping("/transformers") public TransformerView create(@Valid @RequestBody TransformerCreate body){return service.create(body);}
 @GetMapping("/transformers/{id}") public TransformerView get(@PathVariable Long id){return TransformerView.from(service.get(id));}
 @GetMapping("/transformers/{id}/dashboard") public Dashboard dashboard(@PathVariable Long id){return service.dashboard(id);}
 @GetMapping("/transformers/{id}/readings") public PageResponse<ReadingView> readings(@PathVariable Long id,@RequestParam MeasurementType metric,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size,@RequestParam(required=false) Instant from,@RequestParam(required=false) Instant to){
  service.get(id); PageRequest pr=PageRequest.of(safePage(page),clamp(size));
  if(from!=null&&to!=null&&from.isAfter(to))throw new IllegalArgumentException("from must be before to.");
  Page<SensorReading> p=from!=null&&to!=null?readings.findByTransformerIdAndMeasurementTypeAndRecordedAtBetweenOrderByRecordedAtDesc(id,metric,from,to,pr):readings.findByTransformerIdAndMeasurementTypeOrderByRecordedAtDesc(id,metric,pr);
  return ApiDtos.page(p,ReadingView::from);
 }
 @GetMapping("/transformers/{id}/diagnostics") public PageResponse<DiagnosticView> diagnostics(@PathVariable Long id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) String q){service.get(id);PageRequest pr=PageRequest.of(safePage(page),clamp(size));return ApiDtos.page(q==null||q.isBlank()?diagnostics.findByTransformerIdOrderByTestDateDesc(id,pr):diagnostics.searchForTransformer(id,q.trim(),pr),DiagnosticView::from);}
 @PostMapping("/transformers/{id}/diagnostics") public DiagnosticView addDiagnostic(@PathVariable Long id,@Valid @RequestBody DiagnosticCreate x){Transformer t=service.get(id);if("DGA".equalsIgnoreCase(x.testType())&&(x.sampleId()==null||x.sampleId().isBlank()))throw new IllegalArgumentException("A sample ID is required for DGA results so gas ratios are calculated within the same sample.");DiagnosticTest d=new DiagnosticTest(t,x.testType().trim(),x.parameterName().trim().toUpperCase(Locale.ROOT),x.value(),x.unit(),x.testDate(),DataSourceType.IMPORTED,x.laboratory(),x.referenceNote(),x.notes(),x.componentKey(),x.phase());d.setTestMetadata(x.testMethod(),x.samplePoint(),x.testTemperatureC(),x.testVoltage(),x.testDurationSeconds(),x.baselineReference());d.setSampleId(x.sampleId());return DiagnosticView.from(diagnostics.save(d));}
 @GetMapping("/transformers/{id}/dga-analysis") public Map<String,Object> dgaAnalysis(@PathVariable Long id){service.get(id);return dga.analyze(id);}
 @GetMapping("/transformers/{id}/maintenance") public PageResponse<MaintenanceView> maintenance(@PathVariable Long id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){service.get(id);return ApiDtos.page(maintenance.findByTransformerIdOrderByPerformedAtDesc(id,PageRequest.of(safePage(page),clamp(size))),MaintenanceView::from);}
 @PostMapping("/transformers/{id}/maintenance") public MaintenanceView addMaintenance(@PathVariable Long id,@Valid @RequestBody MaintenanceCreate x){MaintenanceRecord m=new MaintenanceRecord(service.get(id),x.activityType(),x.componentKey(),x.description(),x.performedAt(),x.performedBy(),x.findings(),x.nextDueAt());
  if(x.relatedAlertId()!=null){Alert linked=alerts.findById(x.relatedAlertId()).orElseThrow(()->new IllegalArgumentException("Related alert not found"));if(!linked.getTransformer().getId().equals(id))throw new IllegalArgumentException("Related alert belongs to another transformer.");}
  if(x.relatedDiagnosticId()!=null){DiagnosticTest linked=diagnostics.findById(x.relatedDiagnosticId()).orElseThrow(()->new IllegalArgumentException("Related diagnostic not found"));if(!linked.getTransformer().getId().equals(id))throw new IllegalArgumentException("Related diagnostic belongs to another transformer.");}
  m.setRelatedRecords(x.relatedAlertId(),x.relatedDiagnosticId());return MaintenanceView.from(maintenance.save(m));}

 @GetMapping("/transformers/{id}/alerts") public PageResponse<AlertView> alertPage(@PathVariable Long id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){service.get(id);return ApiDtos.page(alerts.findByTransformerIdOrderByCreatedAtDesc(id,PageRequest.of(safePage(page),clamp(size))),AlertView::from);}
 @GetMapping("/transformers/{id}/health-history") public PageResponse<HealthView> healthHistory(@PathVariable Long id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="100") int size){service.get(id);return ApiDtos.page(healthAssessments.findByTransformerIdOrderByAssessmentHourDesc(id,PageRequest.of(safePage(page),clamp(size))),HealthView::from);}
 @GetMapping("/transformers/{id}/notifications") public PageResponse<NotificationView> notificationPage(@PathVariable Long id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){service.get(id);return ApiDtos.page(notifications.findByTransformerIdOrderByCreatedAtDesc(id,PageRequest.of(safePage(page),clamp(size))),NotificationView::from);}
 @PostMapping("/notifications/{notificationId}/read") public NotificationView markNotificationRead(@PathVariable Long notificationId){AlertNotification n=notifications.findById(notificationId).orElseThrow(()->new NoSuchElementException("Notification not found"));n.markRead(Instant.now());return NotificationView.from(notifications.save(n));}
 @PostMapping("/alerts/{alertId}/acknowledge") public AlertView acknowledge(@PathVariable Long alertId,@RequestParam(defaultValue="Operator") String by){
  Alert a=alerts.findById(alertId).orElseThrow(()->new NoSuchElementException("Alert not found"));
  a.acknowledge(by.trim().isEmpty()?"Operator":by.trim(),Instant.now());return AlertView.from(alerts.save(a));
 }

 @PostMapping("/alerts/{alertId}/notes") public AlertView alertNotes(@PathVariable Long alertId,@RequestBody Map<String,String> body){Alert a=alerts.findById(alertId).orElseThrow(()->new NoSuchElementException("Alert not found"));String notes=Objects.toString(body.get("notes"),"");if(notes.length()>1500)throw new IllegalArgumentException("Operator notes cannot exceed 1500 characters.");a.setOperatorNotes(notes);return AlertView.from(alerts.save(a));}
 @GetMapping(value="/transformers/{id}/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter events(@PathVariable Long id){service.get(id);return realtime.subscribe(id);}
 private int safePage(int page){if(page<0)throw new IllegalArgumentException("Page must be zero or greater.");return page;}
 private int clamp(int size){if(size<1)throw new IllegalArgumentException("Page size must be positive.");return Math.min(size,100);}
}
